checkpoint_metrics AS (
  SELECT
    -- ─── A. EXACT CHUNK 04 ID & CUMULATIVE POPULATION RECONCILIATION ────────────
    (SELECT count(*) FROM expected_chunk_04_ids) AS chunk_04_expected_ids_count,

    -- Exact Chunk 04 IDs present in candidate_affidavits
    (SELECT count(*) FROM expected_chunk_04_ids e
     JOIN public.candidate_affidavits a ON a.id = e.id) AS chunk_04_ids_present_count,

    -- Exact Chunk 04 IDs missing from candidate_affidavits
    (SELECT count(*) FROM expected_chunk_04_ids e
     LEFT JOIN public.candidate_affidavits a ON a.id = e.id
     WHERE a.id IS NULL) AS chunk_04_ids_missing_count,

    -- Total candidate_affidavits in table (expected: 3,619)
    (SELECT count(*) FROM public.candidate_affidavits) AS total_affidavits_in_table,

    -- Any affidavits in the table that are NOT part of authorized cumulative population (Chunks 02 + 03 + 04)
    (SELECT count(*) FROM public.candidate_affidavits a
     LEFT JOIN authorized_cumulative_ids c ON c.id = a.id
     WHERE c.id IS NULL) AS unexpected_affidavits_count,

    -- Duplicate IDs in candidate_affidavits
    (SELECT count(*) FROM (
       SELECT id FROM public.candidate_affidavits GROUP BY id HAVING count(*) > 1
     ) d) AS duplicate_ids_count,

    -- IDs outside authorized namespace (0215b22e-0001-0000-0000-...)
    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE id IS NULL OR id::text NOT LIKE '0215b22e-0001-0000-0000-%') AS non_namespace_affidavits_count,

    (SELECT min(id::text) FROM public.candidate_affidavits) AS min_affidavit_id_observed,
    (SELECT max(id::text) FROM public.candidate_affidavits) AS max_affidavit_id_observed,

    -- ─── B. STATE SCOPE & CUMULATIVE PARTITION BOUNDARIES (27 STATES) ───────────
    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE state_code IS NULL OR state_code NOT IN (
       'AP', 'AR', 'AS', 'BR', 'CG', 'DL', 'GA', 'GJ',
       'HR', 'HP', 'JK', 'JH', 'KA', 'KL', 'MP', 'MH',
       'MN', 'ML', 'MZ', 'NL', 'OD', 'PY', 'PB', 'RJ', 'SK', 'TN', 'TS'
     )) AS foreign_state_affidavits_count,

    (SELECT count(DISTINCT state_code) FROM public.candidate_affidavits) AS distinct_states_observed,

    -- Chunk 02 Baseline States
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'AP') AS ap_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'AR') AS ar_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'AS') AS as_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'BR') AS br_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'CG') AS cg_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'DL') AS dl_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'GA') AS ga_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'GJ') AS gj_count,

    -- Chunk 03 Baseline States
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'HR') AS hr_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'HP') AS hp_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'JK') AS jk_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'JH') AS jh_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'KA') AS ka_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'KL') AS kl_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'MP') AS mp_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'MH') AS mh_count,

    -- Chunk 04 New States
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'MN') AS mn_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'ML') AS ml_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'MZ') AS mz_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'NL') AS nl_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'OD') AS od_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'PY') AS py_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'PB') AS pb_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'RJ') AS rj_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'SK') AS sk_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'TN') AS tn_count,
    (SELECT count(*) FROM public.candidate_affidavits WHERE state_code = 'TS') AS ts_count,

    -- ─── C. REFERENTIAL INTEGRITY & ZERO ORPHANS ─────────────────────────────────
    (SELECT count(*) FROM public.candidate_affidavits a
     LEFT JOIN public.candidacies c ON c.id = a.candidacy_id
     WHERE a.candidacy_id IS NULL OR c.id IS NULL) AS orphan_candidacies_count,

    (SELECT count(*) FROM public.candidate_affidavits a
     LEFT JOIN public.canonical_persons p ON p.id = a.person_id
     WHERE a.person_id IS NULL OR p.id IS NULL) AS orphan_persons_count,

    (SELECT count(*) FROM public.candidate_affidavits a
     LEFT JOIN public.provenance_records pr ON pr.id = a.provenance_id
     WHERE a.provenance_id IS NULL OR pr.id IS NULL) AS orphan_provenance_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE provenance_id IS NULL OR provenance_id <> '0215b22e-0000-0000-0000-000000000001'::uuid) AS non_b2_2e_provenance_count,

    -- ─── D. DATA QUALITY & DOMAIN CONSTRAINT CHECKS (EXPLICIT NULL HANDLING) ────
    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE data_status IS NULL OR data_status <> 'OFFICIAL') AS invalid_status_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE candidate_name IS NULL OR length(trim(candidate_name)) = 0) AS invalid_candidate_name_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE constituency_name IS NULL OR length(trim(constituency_name)) = 0) AS invalid_constituency_name_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE party IS NULL OR length(trim(party)) = 0) AS invalid_party_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE ac_no IS NULL OR ac_no < 0) AS invalid_ac_no_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE is_winner IS NULL) AS invalid_is_winner_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE total_liabilities IS NULL OR total_liabilities < 0) AS invalid_liabilities_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE criminal_cases IS NULL OR criminal_cases < 0) AS invalid_criminal_cases_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE serious_criminal_cases IS NULL OR serious_criminal_cases < 0) AS invalid_serious_criminal_cases_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE serious_criminal_cases IS NOT NULL AND criminal_cases IS NOT NULL AND serious_criminal_cases > criminal_cases) AS invalid_serious_exceeds_total_count,

    (SELECT count(*) FROM public.candidate_affidavits 
     WHERE election_year IS NULL OR election_year NOT IN (2020, 2021, 2022, 2023, 2024)) AS invalid_election_year_count,

    -- ─── E. PROTECTED TABLE BASELINES (STRICT PRESERVATION) ──────────────────────
    (SELECT count(*) FROM public.candidacies) AS candidacies_count,
    (SELECT count(*) FROM public.canonical_persons) AS canonical_persons_count,
    (SELECT count(*) FROM public.political_organizations) AS political_organizations_count,
    (SELECT count(*) FROM public.constituencies) AS constituencies_count,
    (SELECT count(*) FROM public.states) AS states_count,
    (SELECT count(*) FROM public.constituency_lineage) AS constituency_lineage_count,
    (SELECT count(*) FROM public.constituency_demographics) AS constituency_demographics_count,
    (SELECT count(*) FROM public.provenance_records) AS provenance_records_count
)
SELECT
  jsonb_build_object(
    'checkpoint', 'W021.5-B2.2-E_CHUNK_04_ACCEPTANCE_CHECKPOINT',
    'timestamp', now(),
    'chunk_identity', jsonb_build_object(
      'chunk_id', '04',
      'scope', 'Candidate Affidavits Part 3 (MN, ML, MZ, NL, OD, PY, PB, RJ, SK, TN, TS)',
      'expected_chunk_ids', chunk_04_expected_ids_count,
      'chunk_ids_present', chunk_04_ids_present_count,
      'chunk_ids_missing', chunk_04_ids_missing_count,
      'unexpected_ids', unexpected_affidavits_count,
      'table_total_observed', total_affidavits_in_table,
      'duplicate_ids', duplicate_ids_count,
      'non_namespace_ids', non_namespace_affidavits_count,
      'min_id_observed', min_affidavit_id_observed,
      'max_id_observed', max_affidavit_id_observed,
      'status', CASE 
        WHEN chunk_04_expected_ids_count = 1150 
         AND chunk_04_ids_present_count = 1150 
         AND chunk_04_ids_missing_count = 0 
         AND unexpected_affidavits_count = 0
         AND total_affidavits_in_table = 3618
         AND duplicate_ids_count = 0
         AND non_namespace_affidavits_count = 0
         AND min_affidavit_id_observed = '0215b22e-0001-0000-0000-000000000001'
         AND max_affidavit_id_observed = '0215b22e-0001-0000-0000-000000004524'
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'state_scope', jsonb_build_object(
      'foreign_state_records', foreign_state_affidavits_count,
      'distinct_states', distinct_states_observed,
      'chunk_02_states', jsonb_build_object(
        'AP', ap_count, 'AR', ar_count, 'AS', as_count, 'BR', br_count,
        'CG', cg_count, 'DL', dl_count, 'GA', ga_count, 'GJ', gj_count
      ),
      'chunk_03_states', jsonb_build_object(
        'HR', hr_count, 'HP', hp_count, 'JK', jk_count, 'JH', jh_count,
        'KA', ka_count, 'KL', kl_count, 'MP', mp_count, 'MH', mh_count
      ),
      'chunk_04_states', jsonb_build_object(
        'MN', mn_count, 'ML', ml_count, 'MZ', mz_count, 'NL', nl_count,
        'OD', od_count, 'PY', py_count, 'PB', pb_count, 'RJ', rj_count,
        'SK', sk_count, 'TN', tn_count, 'TS', ts_count
      ),
      'status', CASE 
        WHEN foreign_state_affidavits_count = 0 
         AND distinct_states_observed = 27 
         AND ap_count = 197 AND ar_count = 55 AND as_count = 126 AND br_count = 267
         AND cg_count = 92 AND dl_count = 228 AND ga_count = 36 AND gj_count = 195
         AND hr_count = 90 AND hp_count = 73 AND jk_count = 85 AND jh_count = 87
         AND ka_count = 229 AND kl_count = 160 AND mp_count = 237 AND mh_count = 311
         AND mn_count = 56 AND ml_count = 57 AND mz_count = 36 AND nl_count = 55
         AND od_count = 153 AND py_count = 28 AND pb_count = 124 AND rj_count = 212
         AND sk_count = 32 AND tn_count = 273 AND ts_count = 124
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'referential_integrity', jsonb_build_object(
      'orphan_candidacies', orphan_candidacies_count,
      'orphan_persons', orphan_persons_count,
      'orphan_provenance', orphan_provenance_count,
      'non_b2_2e_provenance', non_b2_2e_provenance_count,
      'status', CASE 
        WHEN orphan_candidacies_count = 0 
         AND orphan_persons_count = 0 
         AND orphan_provenance_count = 0 
         AND non_b2_2e_provenance_count = 0
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'data_integrity', jsonb_build_object(
      'invalid_status_count', invalid_status_count,
      'invalid_candidate_name_count', invalid_candidate_name_count,
      'invalid_constituency_name_count', invalid_constituency_name_count,
      'invalid_party_count', invalid_party_count,
      'invalid_ac_no_count', invalid_ac_no_count,
      'invalid_is_winner_count', invalid_is_winner_count,
      'invalid_liabilities_count', invalid_liabilities_count,
      'invalid_criminal_cases_count', invalid_criminal_cases_count,
      'invalid_serious_criminal_cases_count', invalid_serious_criminal_cases_count,
      'invalid_serious_exceeds_total_count', invalid_serious_exceeds_total_count,
      'invalid_election_year_count', invalid_election_year_count,
